	/** 
	 * jumpstart the process by instantiating2 Admission
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		admissionId = AdmissionService.getAdmissionInstance()
		.createAdmission( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		AdmissionService.getAdmissionInstance()
				.createAdmission( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.admissionSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Admission : " + successValue.getAdmissionId());
							  if (successValue.getAdmissionId().equals(admissionId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfAdmissionList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Admission test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on admission consumed")
					);
			subscriber.admissionSubscribe( admissionId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Admission : " + successValue.getAdmissionId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfAdmissionList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on admission for admissionId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Admission. 
	 */
	protected Admission read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Admission" );

		Admission entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Admission with primary key" );
		msg.append( admissionId );
		
		AdmissionFetchOneSummary fetchOneSummary = new AdmissionFetchOneSummary( admissionId );

		try {
			entity = AdmissionService.getAdmissionInstance().getAdmission( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Admission " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Admission.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Admission." );

		StringBuilder msg = new StringBuilder( "Failed to update a Admission : " );        
		Admission entity = read();
		UpdateAdmissionCommand command = generateUpdateCommand();
		command.setAdmissionId(entity.getAdmissionId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Admission." );

			// for use later on...
			admissionId = entity.getAdmissionId();

			AdmissionService proxy = AdmissionService.getAdmissionInstance();  

			proxy.updateAdmission( command ).get();

			LOGGER.info( "-- Successfully saved Admission - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + admissionId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Admission.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Admission." );

		Admission entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Admission with id " + admissionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Admission with id " + admissionId );

			throw e;
		}

		try{
			AdmissionService.getAdmissionInstance().delete( new DeleteAdmissionCommand( entity.getAdmissionId() ) ).get();
			LOGGER.info( "-- Successfully deleted Admission with id " + admissionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Admission with id " + admissionId );

			throw e;
		}
	}

	/**
	 * get all Admissions.
	 */
	protected List<Admission> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Admissions:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Admission : " );        
		List<Admission> collection  = new ArrayList<>();

		try {
			// call the static get method on the AdmissionService
			collection = AdmissionService.getAdmissionInstance().getAllAdmission();
			assertNotNull( collection, "An Empty collection of Admission was incorrectly returned.");
			
			// Now print out the values
			Admission entity = null;            
			Iterator<Admission> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAdmissionId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

